mapper.select:
select u.user_id as "userId", u.login_id as "loginId", u.employee_no as "employeeNo", k.name as "name", coalesce(oum.organization_code, k.organization_code) as "organizationCode", o.organization_name as "organizationName", k.rank_name as "rankName", k.employment_status as "employmentStatus", coalesce(oum.position_name, k.position_name) as "positionName", k.retirement_date as "retirementDate", k.last_synced_at as "lastSyncedAt", u.system_use_yn as "systemUseYn", u.status as "status", null as "roleCodes" from users u left join korus_personnel_snapshots k on k.employee_no = u.employee_no left join lateral ( select mapping.organization_code, mapping.position_name from organization_user_mappings mapping where mapping.user_id = u.user_id and mapping.mapping_type in ('POSITION','ORGANIZATION') and mapping.status = 'ACTIVE' and mapping.effective_start_date <= CURRENT_DATE and (mapping.effective_end_date is null or mapping.effective_end_date >= CURRENT_DATE) order by case mapping.mapping_type when 'POSITION' then 0 else 1 end, mapping.effective_start_date desc, mapping.mapping_id desc limit 1 ) oum on true left join organizations o on o.organization_code = coalesce(oum.organization_code, k.organization_code)
u.status != 'DELETED'
and u.employee_no like concat('%', #{criteria.employeeNo}, '%')
and k.name like concat('%', #{criteria.name}, '%')
and coalesce(oum.organization_code, k.organization_code) = #{criteria.organizationCodeFilter}
and k.rank_name like concat('%', #{criteria.rankName}, '%')
and k.employment_status = #{criteria.employmentStatus}
and u.system_use_yn = #{criteria.systemUseYn}
and exists ( select 1 from user_roles ur where ur.user_id = u.user_id and ur.role_code = #{criteria.roleCodeFilter} and ur.status = 'ACTIVE' and ur.valid_start_date <= CURRENT_DATE and (ur.valid_end_date >= CURRENT_DATE or ur.valid_end_date is null) )
and (u.login_id like concat('%', #{criteria.filter}, '%') or u.employee_no like concat('%', #{criteria.filter}, '%') or k.name like concat('%', #{criteria.filter}, '%'))
order by u.user_id limit #{criteria.safeSize} offset #{criteria.offset}

select count(*) from users u left join korus_personnel_snapshots k on k.employee_no = u.employee_no left join lateral ( select mapping.organization_code, mapping.position_name from organization_user_mappings mapping where mapping.user_id = u.user_id and mapping.mapping_type in ('POSITION','ORGANIZATION') and mapping.status = 'ACTIVE' and mapping.effective_start_date <= CURRENT_DATE and (mapping.effective_end_date is null or mapping.effective_end_date >= CURRENT_DATE) order by case mapping.mapping_type when 'POSITION' then 0 else 1 end, mapping.effective_start_date desc, mapping.mapping_id desc limit 1 ) oum on true
u.status != 'DELETED'
and u.employee_no like concat('%', #{criteria.employeeNo}, '%')
and k.name like concat('%', #{criteria.name}, '%')
and coalesce(oum.organization_code, k.organization_code) = #{criteria.organizationCodeFilter}
and k.rank_name like concat('%', #{criteria.rankName}, '%')
and k.employment_status = #{criteria.employmentStatus}
and u.system_use_yn = #{criteria.systemUseYn}
and exists ( select 1 from user_roles ur where ur.user_id = u.user_id and ur.role_code = #{criteria.roleCodeFilter} and ur.status = 'ACTIVE' and ur.valid_start_date <= CURRENT_DATE and (ur.valid_end_date >= CURRENT_DATE or ur.valid_end_date is null) )
and (u.login_id like concat('%', #{criteria.filter}, '%') or u.employee_no like concat('%', #{criteria.filter}, '%') or k.name like concat('%', #{criteria.filter}, '%'))

select count(*) from roles where status = 'ACTIVE' and system_use_yn = 'Y'
